using DelimitedFiles
using Printf
using LinearAlgebra
using GenericSchur
using Plots
using Base.Threads

# ============================================================
# Schwarzschild-AdS scalar spectral QNM solver
#
# Maple exports matrices for the quadratic pencil
#
#     M0 + i*Omega*M1 + Omega^2*M2 = 0.
#
# This Julia code solves the corresponding generalized eigenvalue
# problem, identifies modes stable under the three spectral resolutions
# generated by the Maple assembler, and writes the same diagnostic data
# files as before. In addition, it keeps the search for unstable modes:
# with time dependence exp(-i omega t), unstable modes have Im(Omega) > 0.
#
# Default SAdS setup used here:
#
#     s = 0, ell = 0, xplus = 50
#     N = 90, 95, 100
#
# Default Maple output directory:
#
#     C:/Users/david/Documents/MAPLEFILESOLDPC/SPECTRAL DENYS/09-SAdS/data
#
# The file tag is detected automatically from the available Maple files.
# You can override it with the environment variable SADS_FILETAG.
# ============================================================

# ------------------------------------------------------------
# Precision
# ------------------------------------------------------------

const FILE_DECIMAL_DIGITS = parse(Int, get(ENV, "SADS_FILE_DECIMAL_DIGITS", "200"))
const WORK_DECIMAL_DIGITS = parse(Int, get(ENV, "SADS_WORK_DECIMAL_DIGITS", "220"))

setprecision(BigFloat, WORK_DECIMAL_DIGITS; base = 10)

bf(s::AbstractString) = parse(BigFloat, s)

# ------------------------------------------------------------
# Problem parameters
# ------------------------------------------------------------

const SPIN = parse(Int, get(ENV, "SADS_SPIN", "0"))
const ELL  = parse(Int, get(ENV, "SADS_ELL",  "0"))

# xplus = r_+/R. Horowitz-Hubeny values such as r_+ = 50 with R = 1
# correspond to XPLUS = 50 here.
const XPLUS_INPUT = get(ENV, "SADS_XPLUS", "50")
const XPLUS = bf(XPLUS_INPUT)

function integerish_tag(s::AbstractString)
    t = strip(s)
    try
        v = parse(Float64, t)
        if isfinite(v) && abs(v - round(v)) < 100 * eps(Float64) * max(1.0, abs(v))
            return string(Int(round(v)))
        end
    catch
        # Keep the original string if it is not a simple floating-point number.
    end
    return t
end

function atag_from_xplus_string(s::AbstractString)
    v = parse(Float64, strip(s))
    return string(Int(round(1000 * v)))
end

# These tags only affect file names. They should match how Maple wrote them.
const XPLUS_TAG = get(ENV, "SADS_XPLUS_TAG", integerish_tag(XPLUS_INPUT))
const ATAG_TAG  = get(ENV, "SADS_ATAG", atag_from_xplus_string(XPLUS_INPUT))

function validate_sector(s::Integer, ell::Integer)
    if s == 0
        ell >= 0 || error("For s=0 one needs ell >= 0.")
    elseif s == 1
        ell >= 1 || error("For s=1 one needs ell >= 1.")
    elseif s == 2
        ell >= 2 || error("For s=2 one needs ell >= 2.")
    else
        error("Unknown spin sector s=$s. Use s=0, 1, or 2.")
    end
    return nothing
end

validate_sector(SPIN, ELL)

const EPSILON = 1 - SPIN^2

function sector_name(s::Integer)
    if s == 0
        return "massless scalar"
    elseif s == 1
        return "electromagnetic"
    elseif s == 2
        return "gravitational"
    else
        return "unknown"
    end
end

# ------------------------------------------------------------
# Directories and spectral resolutions
# ------------------------------------------------------------

const DATA_DIR = get(ENV, "SADS_DATA_DIR",
    raw"C:\Users\david\Documents\MAPLEFILESOLDPC\SPECTRAL DENYS\09-SAdS\data")

function parse_n_vals(s::AbstractString)
    vals = [parse(Int, strip(x)) for x in split(s, ",") if !isempty(strip(x))]
    length(vals) == 3 || error("SADS_N_VALS must contain exactly three comma-separated integers, e.g. 90,95,100")
    return Tuple(vals)
end

const N_VALS = parse_n_vals(get(ENV, "SADS_N_VALS", "90,95,100"))

# ------------------------------------------------------------
# File-tag detection
# ------------------------------------------------------------

function default_filetag_candidates()
    base = "s$(SPIN)_L$(ELL)"
    tags = String[]

    # User override has priority.
    if haskey(ENV, "SADS_FILETAG")
        push!(tags, ENV["SADS_FILETAG"])
    end

    # The tag recommended for the fixed Maple assembler.
    push!(tags, "$(base)_xp$(XPLUS_TAG)_a$(ATAG_TAG)")

    # Common alternatives, kept to make the Julia script robust against
    # harmless changes in the order of the Maple cat(...) arguments.
    push!(tags, "$(base)_a$(ATAG_TAG)_xp$(XPLUS_TAG)")
    push!(tags, "$(base)_a$(ATAG_TAG)")
    push!(tags, "$(base)_a$(XPLUS_TAG)")
    push!(tags, "$(base)_a$(XPLUS_INPUT)")
    push!(tags, "$(base)_xp$(XPLUS_TAG)")

    # If Maple printed a floating integer as 50. or 50.0, these cover it.
    if occursin(r"^[0-9]+$", XPLUS_TAG)
        push!(tags, "$(base)_a$(XPLUS_TAG).")
        push!(tags, "$(base)_a$(XPLUS_TAG).0")
        push!(tags, "$(base)_xp$(XPLUS_TAG).")
        push!(tags, "$(base)_xp$(XPLUS_TAG).0")
    end

    return unique(tags)
end

matfile_with_tag(prefix::AbstractString, n::Integer, tag::AbstractString) =
    joinpath(DATA_DIR, "$(prefix)-$(n)-$(tag).mat")

function matrix_files_exist_for_tag(tag::AbstractString)
    for n in N_VALS
        for prefix in ("M0", "M1", "M2")
            isfile(matfile_with_tag(prefix, n, tag)) || return false
        end
    end
    return true
end

function scan_filetags_from_directory()
    isdir(DATA_DIR) || return String[]

    n0 = N_VALS[1]
    pattern = Regex("^M0-$(n0)-(.+)\\.mat\$")
    base = "s$(SPIN)_L$(ELL)"
    tags = String[]

    for fname in readdir(DATA_DIR)
        m = match(pattern, fname)
        m === nothing && continue
        tag = m.captures[1]
        occursin(base, tag) || continue
        matrix_files_exist_for_tag(tag) || continue
        push!(tags, tag)
    end

    return sort(unique(tags))
end

function detect_filetag()
    if haskey(ENV, "SADS_FILETAG")
        tag = ENV["SADS_FILETAG"]
        matrix_files_exist_for_tag(tag) || error(
            "SADS_FILETAG=$tag was supplied, but the required M0/M1/M2 files were not found in DATA_DIR=$DATA_DIR"
        )
        return tag
    end

    for tag in default_filetag_candidates()
        if matrix_files_exist_for_tag(tag)
            return tag
        end
    end

    scanned = scan_filetags_from_directory()
    if !isempty(scanned)
        return first(scanned)
    end

    msg = IOBuffer()
    println(msg, "Could not detect a complete Maple file tag.")
    println(msg, "DATA_DIR = ", DATA_DIR)
    println(msg, "Tried these tags:")
    for tag in default_filetag_candidates()
        println(msg, "  ", tag)
    end
    println(msg, "Expected files of the form:")
    println(msg, "  M0-$(N_VALS[1])-<tag>.mat")
    println(msg, "  M1-$(N_VALS[1])-<tag>.mat")
    println(msg, "  M2-$(N_VALS[1])-<tag>.mat")
    if isdir(DATA_DIR)
        println(msg, "Files currently visible in DATA_DIR:")
        visible_files = sort(readdir(DATA_DIR))
        for fname in Iterators.take(visible_files, 30)
            println(msg, "  ", fname)
        end
    else
        println(msg, "DATA_DIR does not exist.")
    end
    error(String(take!(msg)))
end

const FILETAG = detect_filetag()

const OUT_DIR = get(ENV, "SADS_OUT_DIR", joinpath(DATA_DIR, "Julia", FILETAG))
mkpath(OUT_DIR)

matfile(prefix::AbstractString, n::Integer) = matfile_with_tag(prefix, n, FILETAG)
outfile(name::AbstractString) = joinpath(OUT_DIR, name)

# ------------------------------------------------------------
# Filters and classification
# ------------------------------------------------------------

const DISPLAY_ZERO_TOL = bf(get(ENV, "SADS_DISPLAY_ZERO_TOL", "1e-20"))
const PLOT_ZERO_TOL    = bf(get(ENV, "SADS_PLOT_ZERO_TOL",    "1e-12"))

# Stable-mode matching tolerance between the three N runs.
const STABLE_RELTOL = bf(get(ENV, "SADS_STABLE_RELTOL", "1e-4"))
const STABLE_ABSTOL = bf(get(ENV, "SADS_STABLE_ABSTOL", "1e-4"))

# The generalized eigenproblem may contain a static Omega = 0 solution.
# This is normally not counted as a QNM.
const DISCARD_ZERO_MODE = lowercase(get(ENV, "SADS_DISCARD_ZERO_MODE", "true")) == "true"
const ZERO_MODE_TOL = bf(get(ENV, "SADS_ZERO_MODE_TOL", "1e-30"))

# With exp(-i omega t):
#   Im(Omega) < 0  damped/stable in time,
#   Im(Omega) > 0  unstable in time.
# We deliberately do not discard unstable modes from the candidate set.
const SEARCH_UNSTABLE_MODES = lowercase(get(ENV, "SADS_SEARCH_UNSTABLE", "true")) == "true"
const DAMPING_TOL = bf(get(ENV, "SADS_DAMPING_TOL", "1e-18"))

# Keep only one representative branch of the +/- Re(Omega) symmetry.
const KEEP_REPRESENTATIVE_BRANCH = lowercase(get(ENV, "SADS_KEEP_REPRESENTATIVE_BRANCH", "false")) == "true"
const REPRESENTATIVE_RE_TOL = bf(get(ENV, "SADS_REPRESENTATIVE_RE_TOL", "1e-10"))

# Threshold used only to split modes into oscillatory and purely imaginary lists.
const PURE_IMAG_RE_TOL = bf(get(ENV, "SADS_PURE_IMAG_RE_TOL", "1e-10"))

# Plot settings.
const USE_PLOTLYJS = lowercase(get(ENV, "SADS_USE_PLOTLYJS", "true")) == "true"
const SAVE_HTML_PLOTS = lowercase(get(ENV, "SADS_SAVE_HTML_PLOTS", "true")) == "true"

# ------------------------------------------------------------
# Matrix I/O and quadratic eigenvalue problem
# ------------------------------------------------------------

function read_big_matrix(path::AbstractString)
    isfile(path) || error("Missing input file: $path")

    A = readdlm(path, BigFloat)
    A = Matrix{BigFloat}(A)

    size(A, 1) == size(A, 2) ||
        error("Matrix is not square: $path has size $(size(A))")

    return A
end

function qep_eigs(M0::AbstractMatrix{T},
                  M1::AbstractMatrix{T},
                  M2::AbstractMatrix{T}) where {T<:Real}

    n = size(M0, 1)

    @assert size(M0, 2) == n "M0 must be square"
    @assert size(M1) == (n, n) "M1 must match size(M0)"
    @assert size(M2) == (n, n) "M2 must match size(M0)"

    Tc = Complex{T}

    Z = zeros(Tc, n, n)
    I_n = Matrix{Tc}(I, n, n)

    M0c = Tc.(M0)
    M1c = Tc.(M1)
    M2c = Tc.(M2)

    # gamma = i gives M0 + i*Omega*M1 + Omega^2*M2 = 0.
    gamma = complex(zero(T), one(T))

    # Linearization A v = Omega B v with v = [b; Omega*b].
    A = [Z      I_n;
        -M0c   -gamma*M1c]

    B = [I_n   Z;
         Z     M2c]

    vals = try
        eigvals(A, B)
    catch err
        @warn "eigvals(A, B) failed; falling back to eigvals(B \\ A)" exception=(err, catch_backtrace())
        eigvals(B \ A)
    end

    return Tc.(vals)
end

function finite_modes(vals)
    return [Omega for Omega in vals if isfinite(real(Omega)) && isfinite(imag(Omega))]
end

function is_candidate_mode(Omega)
    isfinite(real(Omega)) && isfinite(imag(Omega)) || return false

    if DISCARD_ZERO_MODE && abs(Omega) < ZERO_MODE_TOL
        return false
    end

    if KEEP_REPRESENTATIVE_BRANCH && real(Omega) < -REPRESENTATIVE_RE_TOL
        return false
    end

    if !SEARCH_UNSTABLE_MODES && imag(Omega) > DAMPING_TOL
        return false
    end

    return true
end

function candidate_modes(vals)
    return [Omega for Omega in vals if is_candidate_mode(Omega)]
end

function is_damped_mode(Omega)
    return imag(Omega) < -DAMPING_TOL
end

function is_unstable_mode(Omega)
    return imag(Omega) > DAMPING_TOL
end

function is_neutral_mode(Omega)
    return abs(imag(Omega)) <= DAMPING_TOL
end

function load_and_solve(n::Integer)
    M0 = read_big_matrix(matfile("M0", n))
    M1 = read_big_matrix(matfile("M1", n))
    M2 = read_big_matrix(matfile("M2", n))

    vals = qep_eigs(M0, M1, M2)
    vals_finite = finite_modes(vals)
    vals_candidate = candidate_modes(vals_finite)

    if length(vals_finite) != length(vals)
        @warn "Discarded non-finite eigenvalues" n=n total=length(vals) finite=length(vals_finite)
    end

    if length(vals_candidate) != length(vals_finite)
        @info "Applied nonphysical/candidate filters" n=n finite=length(vals_finite) candidates=length(vals_candidate)
    end

    return vals_finite, vals_candidate
end

# ------------------------------------------------------------
# Stable-mode identification across resolutions
# ------------------------------------------------------------

function nearest_mode(Omega, vals, used::AbstractVector{Bool})
    jmin = 0
    dmin = BigFloat(Inf)

    for j in eachindex(vals)
        used[j] && continue
        d = abs(vals[j] - Omega)
        if d < dmin
            dmin = d
            jmin = j
        end
    end

    return jmin, dmin
end

function nearest_mode_unrestricted(Omega, vals)
    jmin = 0
    dmin = BigFloat(Inf)

    for j in eachindex(vals)
        d = abs(vals[j] - Omega)
        if d < dmin
            dmin = d
            jmin = j
        end
    end

    return jmin, dmin
end

function sort_mode_indices(vals)
    return sortperm(
        1:length(vals),
        by = k -> (abs(imag(vals[k])), real(vals[k]))
    )
end

function sort_modes(vals)
    isempty(vals) && return vals
    return vals[sort_mode_indices(vals)]
end

function stable_modes(e1, e2, e3; reltol = STABLE_RELTOL, abstol = STABLE_ABSTOL)
    stable = Complex{BigFloat}[]

    e1m = Complex{BigFloat}[]
    e2m = Complex{BigFloat}[]
    e3m = Complex{BigFloat}[]

    err12 = BigFloat[]
    err23 = BigFloat[]
    err13 = BigFloat[]

    used2 = falses(length(e2))
    used3 = falses(length(e3))

    for Omega1 in e1
        j2, d12 = nearest_mode(Omega1, e2, used2)
        j2 == 0 && continue

        Omega2 = e2[j2]

        j3, d23 = nearest_mode(Omega2, e3, used3)
        j3 == 0 && continue

        Omega3 = e3[j3]
        d13 = abs(Omega1 - Omega3)

        scale = max(BigFloat(1), abs(Omega1), abs(Omega2), abs(Omega3))
        tol = max(abstol, reltol * scale)

        if max(d12, d23, d13) > tol
            continue
        end

        Omega_avg = (Omega1 + Omega2 + Omega3) / 3

        push!(stable, Omega_avg)
        push!(e1m, Omega1)
        push!(e2m, Omega2)
        push!(e3m, Omega3)

        push!(err12, d12)
        push!(err23, d23)
        push!(err13, d13)

        used2[j2] = true
        used3[j3] = true
    end

    p = sort_mode_indices(stable)

    return stable[p], e1m[p], e2m[p], e3m[p], err12[p], err23[p], err13[p]
end

function split_stable_modes(stable)
    pure_imag = Complex{BigFloat}[]
    oscillatory = Complex{BigFloat}[]

    for Omega in stable
        if abs(real(Omega)) < PURE_IMAG_RE_TOL
            push!(pure_imag, Omega)
        else
            push!(oscillatory, Omega)
        end
    end

    return sort_modes(oscillatory), sort_modes(pure_imag)
end

function split_by_time_behavior(vals)
    damped = Complex{BigFloat}[]
    unstable = Complex{BigFloat}[]
    neutral = Complex{BigFloat}[]

    for Omega in vals
        if is_damped_mode(Omega)
            push!(damped, Omega)
        elseif is_unstable_mode(Omega)
            push!(unstable, Omega)
        else
            push!(neutral, Omega)
        end
    end

    return sort_modes(damped), sort_modes(unstable), sort_modes(neutral)
end

# ------------------------------------------------------------
# File output
# ------------------------------------------------------------

function write_metadata(io)
    println(io, "# Background: Schwarzschild-AdS")
    println(io, "# Sector: s = ", SPIN,
                ", field = ", sector_name(SPIN),
                ", ell = ", ELL,
                ", epsilon = ", EPSILON)
    println(io, "# xplus = r_+/R = ", XPLUS)
    println(io, "# File tag: ", FILETAG)
    println(io, "# Pencil: M0 + i*Omega*M1 + Omega^2*M2 = 0")
    println(io, "# Time dependence: exp(-i omega t)")
    println(io, "# Damped modes: Im(Omega) < 0")
    println(io, "# Unstable modes: Im(Omega) > 0")
end

function save_complex_pairs(filename::AbstractString, vals; title::AbstractString = "")
    open(filename, "w") do io
        !isempty(title) && println(io, "# ", title)
        write_metadata(io)
        println(io, "# Re(Omega) Im(Omega)")
        for Omega in vals
            println(io, real(Omega), " ", imag(Omega))
        end
    end
end

function with_suffix(filename::AbstractString, suffix::AbstractString)
    root, ext = splitext(filename)
    isempty(ext) && (ext = ".txt")
    return root * suffix * ext
end

function readable_value(x::Real; chop::Bool = false)
    y = chop && abs(x) < DISPLAY_ZERO_TOL ? zero(BigFloat) : x
    return @sprintf("% .16f", y)
end

function readable_error(x::Real)
    return @sprintf("%.6e", x)
end

const VALUE_WIDTH = 22
const ERROR_WIDTH = 16

function write_stable_summary_header(io)
    print(io, lpad("k", 5))
    print(io, "  ", lpad("Re(avg)", VALUE_WIDTH))
    print(io, "  ", lpad("Im(avg)", VALUE_WIDTH))
    print(io, "  ", lpad("err12", ERROR_WIDTH))
    print(io, "  ", lpad("err23", ERROR_WIDTH))
    print(io, "  ", lpad("err13", ERROR_WIDTH))
    print(io, "  ", lpad("maxerr", ERROR_WIDTH))
    println(io)
    println(io, repeat("-", 5 + 2 * (VALUE_WIDTH + 2) + 4 * (ERROR_WIDTH + 2)))
end

function write_stable_summary_row(io, k::Integer, Omega, d12, d23, d13)
    maxerr = max(d12, d23, d13)

    print(io, lpad(string(k), 5))
    print(io, "  ", lpad(readable_value(real(Omega); chop = true), VALUE_WIDTH))
    print(io, "  ", lpad(readable_value(imag(Omega); chop = true), VALUE_WIDTH))
    print(io, "  ", lpad(readable_error(d12), ERROR_WIDTH))
    print(io, "  ", lpad(readable_error(d23), ERROR_WIDTH))
    print(io, "  ", lpad(readable_error(d13), ERROR_WIDTH))
    print(io, "  ", lpad(readable_error(maxerr), ERROR_WIDTH))
    println(io)
end

function save_stable_modes(filename::AbstractString,
                           stable, e1m, e2m, e3m,
                           err12, err23, err13;
                           title::AbstractString = "Stable SAdS QNM modes")

    details_filename = with_suffix(filename, "_details")
    full_filename = with_suffix(filename, "_full_precision")

    open(filename, "w") do io
        println(io, "# ", title)
        write_metadata(io)
        println(io, "# Re/Im are printed with 16 decimal places.")
        println(io, "# Errors are printed in scientific notation with 6 digits.")
        println(io, "# In Re/Im columns only, values with |x| < ", DISPLAY_ZERO_TOL, " are printed as 0.")
        println(io, "# For all digits, see: ", basename(full_filename))
        println(io)

        write_stable_summary_header(io)

        for k in eachindex(stable)
            write_stable_summary_row(io, k, stable[k], err12[k], err23[k], err13[k])
        end
    end

    open(details_filename, "w") do io
        println(io, "# ", title, ", detailed readable report")
        write_metadata(io)
        println(io, "# Re/Im are printed with 16 decimal places.")
        println(io, "# Errors are printed in scientific notation with 6 digits.")
        println(io, "# In Re/Im columns only, values with |x| < ", DISPLAY_ZERO_TOL, " are printed as 0.")
        println(io)

        for k in eachindex(stable)
            println(io, "mode ", k)
            println(io, "  avg  Re = ", readable_value(real(stable[k]); chop = true),
                        "    Im = ", readable_value(imag(stable[k]); chop = true))
            println(io, "  n1   Re = ", readable_value(real(e1m[k]); chop = true),
                        "    Im = ", readable_value(imag(e1m[k]); chop = true))
            println(io, "  n2   Re = ", readable_value(real(e2m[k]); chop = true),
                        "    Im = ", readable_value(imag(e2m[k]); chop = true))
            println(io, "  n3   Re = ", readable_value(real(e3m[k]); chop = true),
                        "    Im = ", readable_value(imag(e3m[k]); chop = true))
            println(io, "  errors: |n1-n2| = ", readable_error(err12[k]),
                        "    |n2-n3| = ", readable_error(err23[k]),
                        "    |n1-n3| = ", readable_error(err13[k]))
            println(io)
        end
    end

    open(full_filename, "w") do io
        println(io,
            "# Re(avg) Im(avg) ",
            "Re(n1) Im(n1) ",
            "Re(n2) Im(n2) ",
            "Re(n3) Im(n3) ",
            "|n1-n2| |n2-n3| |n1-n3|"
        )

        for k in eachindex(stable)
            println(io,
                real(stable[k]), " ",
                imag(stable[k]), " ",
                real(e1m[k]), " ",
                imag(e1m[k]), " ",
                real(e2m[k]), " ",
                imag(e2m[k]), " ",
                real(e3m[k]), " ",
                imag(e3m[k]), " ",
                err12[k], " ",
                err23[k], " ",
                err13[k]
            )
        end
    end

    println(title, " written to: ", filename)
    println("Readable details written to: ", details_filename)
    println("Full-precision data written to: ", full_filename)
end

function save_mode_table(filename::AbstractString, vals; title::AbstractString)
    open(filename, "w") do io
        println(io, "# ", title)
        write_metadata(io)
        println(io, "# k Re(Omega) Im(Omega)")
        for k in eachindex(vals)
            println(io, k, " ", real(vals[k]), " ", imag(vals[k]))
        end
    end
    println(title, " written to: ", filename)
end

# ------------------------------------------------------------
# Plot helpers
# ------------------------------------------------------------

function plot_xy(vals; chop_real::Bool = false)
    x = Float64[]
    y = Float64[]

    tol = Float64(PLOT_ZERO_TOL)

    for Omega in vals
        xr = Float64(real(Omega))
        yi = Float64(imag(Omega))

        isfinite(xr) && isfinite(yi) || continue

        if chop_real && abs(xr) < tol
            xr = 0.0
        end

        push!(x, xr)
        push!(y, yi)
    end

    return x, y
end

function recommended_xlims(vals...)
    xs = Float64[]

    for arr in vals
        for Omega in arr
            xr = Float64(real(Omega))
            isfinite(xr) || continue
            push!(xs, xr)
        end
    end

    isempty(xs) && return (-1.0, 1.0)

    maxabsx = maximum(abs.(xs))

    if maxabsx < Float64(PLOT_ZERO_TOL)
        return (-0.1, 0.1)
    end

    pad = max(0.1, 0.15 * maxabsx)
    return (-maxabsx - pad, maxabsx + pad)
end

function recommended_ylims(vals...)
    ys = Float64[]

    for arr in vals
        for Omega in arr
            yi = Float64(imag(Omega))
            isfinite(yi) || continue
            push!(ys, yi)
        end
    end

    isempty(ys) && return (-1.0, 1.0)

    ymin = minimum(ys)
    ymax = maximum(ys)
    pad = max(0.5, 0.05 * max(ymax - ymin, eps(Float64)))

    return (ymin - pad, ymax + pad)
end

function select_plot_backend()
    USE_PLOTLYJS || return nothing

    try
        plotlyjs()
    catch err
        @warn "plotlyjs() failed; using the current Plots backend" exception=(err, catch_backtrace())
    end

    return nothing
end

function save_plot_files(p, stem::AbstractString)
    pngfile = outfile(stem * ".png")
    try
        savefig(p, pngfile)
        println("Plot written to: ", pngfile)
    catch err
        @warn "Could not save PNG plot" file=pngfile exception=(err, catch_backtrace())
    end

    if SAVE_HTML_PLOTS
        htmlfile = outfile(stem * ".html")
        try
            savefig(p, htmlfile)
            println("Plot written to: ", htmlfile)
        catch err
            @warn "Could not save HTML plot" file=htmlfile exception=(err, catch_backtrace())
        end
    end
end

# ------------------------------------------------------------
# Main run
# ------------------------------------------------------------

println("Julia threads: ", Threads.nthreads())
println("Reading Maple data from: ", DATA_DIR)
println("Writing Julia output to: ", OUT_DIR)
println("Background: Schwarzschild-AdS")
println("Spin sector s = ", SPIN, " (", sector_name(SPIN), ")")
println("ell = ", ELL)
println("epsilon = 1 - s^2 = ", EPSILON)
println("xplus = r_+/R = ", XPLUS)
println("xplus file tag = ", XPLUS_TAG)
println("a/atag file tag = ", ATAG_TAG)
println("Using file tag: ", FILETAG)
println("N values: ", N_VALS)
println("Matrix pencil: M0 + i*Omega*M1 + Omega^2*M2 = 0")
println("Candidate filters:")
println("  discard zero mode: ", DISCARD_ZERO_MODE, " with tol = ", ZERO_MODE_TOL)
println("  keep representative Re(Omega) >= 0 branch: ", KEEP_REPRESENTATIVE_BRANCH)
println("  search unstable modes Im(Omega) > 0: ", SEARCH_UNSTABLE_MODES)
println("  damping/instability classification tol: ", DAMPING_TOL)

# Check all required files before launching expensive solves.
for n in N_VALS
    for prefix in ("M0", "M1", "M2")
        f = matfile(prefix, n)
        isfile(f) || error("Required input file does not exist: $f")
    end
end

# Solve the three problems.
finite1, e1 = load_and_solve(N_VALS[1])
finite2, e2 = load_and_solve(N_VALS[2])
finite3, e3 = load_and_solve(N_VALS[3])

println("Number of finite modes:")
println("N = ", N_VALS[1], ": ", length(finite1))
println("N = ", N_VALS[2], ": ", length(finite2))
println("N = ", N_VALS[3], ": ", length(finite3))

println("Number of candidate modes after filters:")
println("N = ", N_VALS[1], ": ", length(e1))
println("N = ", N_VALS[2], ": ", length(e2))
println("N = ", N_VALS[3], ": ", length(e3))

# Split candidates at each N by time behavior.
e1_damped, e1_unstable, e1_neutral = split_by_time_behavior(e1)
e2_damped, e2_unstable, e2_neutral = split_by_time_behavior(e2)
e3_damped, e3_unstable, e3_neutral = split_by_time_behavior(e3)

println("Candidate mode counts by time behavior:")
println("N = ", N_VALS[1], ": damped = ", length(e1_damped), ", unstable = ", length(e1_unstable), ", neutral = ", length(e1_neutral))
println("N = ", N_VALS[2], ": damped = ", length(e2_damped), ", unstable = ", length(e2_unstable), ", neutral = ", length(e2_neutral))
println("N = ", N_VALS[3], ": damped = ", length(e3_damped), ", unstable = ", length(e3_unstable), ", neutral = ", length(e3_neutral))

# Save the raw finite spectra and the filtered candidate spectra.
save_complex_pairs(outfile("spectrum_finite-N$(N_VALS[1])-$(FILETAG).dat"), finite1;
    title = "Finite generalized-eigenvalue spectrum, N=$(N_VALS[1])")
save_complex_pairs(outfile("spectrum_finite-N$(N_VALS[2])-$(FILETAG).dat"), finite2;
    title = "Finite generalized-eigenvalue spectrum, N=$(N_VALS[2])")
save_complex_pairs(outfile("spectrum_finite-N$(N_VALS[3])-$(FILETAG).dat"), finite3;
    title = "Finite generalized-eigenvalue spectrum, N=$(N_VALS[3])")

save_complex_pairs(outfile("spectrum_candidates-N$(N_VALS[1])-$(FILETAG).dat"), e1;
    title = "Candidate QNM spectrum after filters, N=$(N_VALS[1])")
save_complex_pairs(outfile("spectrum_candidates-N$(N_VALS[2])-$(FILETAG).dat"), e2;
    title = "Candidate QNM spectrum after filters, N=$(N_VALS[2])")
save_complex_pairs(outfile("spectrum_candidates-N$(N_VALS[3])-$(FILETAG).dat"), e3;
    title = "Candidate QNM spectrum after filters, N=$(N_VALS[3])")

save_complex_pairs(outfile("spectrum_candidates_damped-N$(N_VALS[1])-$(FILETAG).dat"), e1_damped;
    title = "Damped candidate QNM spectrum, N=$(N_VALS[1])")
save_complex_pairs(outfile("spectrum_candidates_damped-N$(N_VALS[2])-$(FILETAG).dat"), e2_damped;
    title = "Damped candidate QNM spectrum, N=$(N_VALS[2])")
save_complex_pairs(outfile("spectrum_candidates_damped-N$(N_VALS[3])-$(FILETAG).dat"), e3_damped;
    title = "Damped candidate QNM spectrum, N=$(N_VALS[3])")

save_complex_pairs(outfile("spectrum_candidates_unstable-N$(N_VALS[1])-$(FILETAG).dat"), e1_unstable;
    title = "Unstable candidate QNM spectrum, N=$(N_VALS[1])")
save_complex_pairs(outfile("spectrum_candidates_unstable-N$(N_VALS[2])-$(FILETAG).dat"), e2_unstable;
    title = "Unstable candidate QNM spectrum, N=$(N_VALS[2])")
save_complex_pairs(outfile("spectrum_candidates_unstable-N$(N_VALS[3])-$(FILETAG).dat"), e3_unstable;
    title = "Unstable candidate QNM spectrum, N=$(N_VALS[3])")

# Identify stable modes across resolutions using all candidates, including
# any unstable modes. This is essential for the instability search.
stable, e1m, e2m, e3m, err12, err23, err13 =
    stable_modes(e1, e2, e3;
        reltol = STABLE_RELTOL,
        abstol = STABLE_ABSTOL
    )

println("Number of stable candidate QNM modes found: ", length(stable))

save_stable_modes(
    outfile("stable_modes-$(FILETAG).txt"),
    stable, e1m, e2m, e3m,
    err12, err23, err13;
    title = "Stable SAdS QNM modes"
)

stable_damped, stable_unstable, stable_neutral = split_by_time_behavior(stable)
oscillatory_modes, pure_imag_modes = split_stable_modes(stable)

println("Number of stable damped modes: ", length(stable_damped))
println("Number of stable unstable modes: ", length(stable_unstable))
println("Number of stable neutral modes: ", length(stable_neutral))
println("Number of stable oscillatory modes: ", length(oscillatory_modes))
println("Number of stable purely imaginary modes: ", length(pure_imag_modes))

save_mode_table(
    outfile("stable_modes_damped-$(FILETAG).dat"),
    stable_damped;
    title = "Stable damped SAdS QNM modes"
)

save_mode_table(
    outfile("stable_modes_unstable-$(FILETAG).dat"),
    stable_unstable;
    title = "Stable unstable SAdS QNM modes"
)

save_mode_table(
    outfile("stable_modes_neutral-$(FILETAG).dat"),
    stable_neutral;
    title = "Stable neutral SAdS QNM modes"
)

save_mode_table(
    outfile("stable_modes_oscillatory-$(FILETAG).dat"),
    oscillatory_modes;
    title = "Stable oscillatory SAdS QNM modes"
)

save_mode_table(
    outfile("stable_modes_pure_imag-$(FILETAG).dat"),
    pure_imag_modes;
    title = "Stable purely imaginary SAdS QNM modes"
)

# ------------------------------------------------------------
# Plots
# ------------------------------------------------------------

select_plot_backend()

x1, y1 = plot_xy(e1)
x2, y2 = plot_xy(e2)
x3, y3 = plot_xy(e3)
xs, ys = plot_xy(stable; chop_real = true)
xd, yd = plot_xy(stable_damped; chop_real = true)
xu, yu = plot_xy(stable_unstable; chop_real = true)
xo, yo = plot_xy(oscillatory_modes; chop_real = true)
xpi, ypi = plot_xy(pure_imag_modes; chop_real = true)

plot_source = isempty(stable) ? vcat(e1, e2, e3) : stable
xlo, xhi = recommended_xlims(plot_source)
ylo, yhi = recommended_ylims(plot_source)

p = scatter(x1, y1;
    ms = 2.5,
    alpha = 0.25,
    label = "N=$(N_VALS[1]) candidates"
)

scatter!(p, x2, y2;
    ms = 2.5,
    alpha = 0.25,
    label = "N=$(N_VALS[2]) candidates"
)

scatter!(p, x3, y3;
    ms = 2.5,
    alpha = 0.25,
    label = "N=$(N_VALS[3]) candidates"
)

scatter!(p, xs, ys;
    ms = 5,
    alpha = 1.0,
    label = "stable"
)

hline!(p, [0.0]; label = "Im Omega = 0", linestyle = :dash, alpha = 0.4)

xlims!(p, xlo, xhi)
ylims!(p, ylo, yhi)

xlabel!(p, "Re Omega")
ylabel!(p, "Im Omega")
title!(p, "SAdS QNMs: s=$(SPIN), ell=$(ELL), xplus=$(XPLUS_TAG)")

save_plot_files(p, "qnm_plot_all-$(FILETAG)")

stableplot = scatter(xs, ys;
    ms = 5,
    alpha = 1.0,
    label = "stable"
)

hline!(stableplot, [0.0]; label = "Im Omega = 0", linestyle = :dash, alpha = 0.4)

xlims!(stableplot, xlo, xhi)
ylims!(stableplot, ylo, yhi)

xlabel!(stableplot, "Re Omega")
ylabel!(stableplot, "Im Omega")
title!(stableplot, "Stable SAdS QNMs: s=$(SPIN), ell=$(ELL), xplus=$(XPLUS_TAG)")

save_plot_files(stableplot, "qnm_plot_stable-$(FILETAG)")

if !isempty(stable_damped)
    xlo_d, xhi_d = recommended_xlims(stable_damped)
    ylo_d, yhi_d = recommended_ylims(stable_damped)

    dampedplot = scatter(xd, yd;
        ms = 5,
        alpha = 1.0,
        label = "stable damped"
    )

    xlims!(dampedplot, xlo_d, xhi_d)
    ylims!(dampedplot, ylo_d, yhi_d)

    xlabel!(dampedplot, "Re Omega")
    ylabel!(dampedplot, "Im Omega")
    title!(dampedplot, "Damped SAdS QNMs: s=$(SPIN), ell=$(ELL), xplus=$(XPLUS_TAG)")

    save_plot_files(dampedplot, "qnm_plot_damped-$(FILETAG)")
end

if !isempty(stable_unstable)
    xlo_u, xhi_u = recommended_xlims(stable_unstable)
    ylo_u, yhi_u = recommended_ylims(stable_unstable)

    unstableplot = scatter(xu, yu;
        ms = 5,
        alpha = 1.0,
        label = "stable unstable"
    )

    hline!(unstableplot, [0.0]; label = "Im Omega = 0", linestyle = :dash, alpha = 0.4)

    xlims!(unstableplot, xlo_u, xhi_u)
    ylims!(unstableplot, ylo_u, yhi_u)

    xlabel!(unstableplot, "Re Omega")
    ylabel!(unstableplot, "Im Omega")
    title!(unstableplot, "Unstable SAdS QNMs: s=$(SPIN), ell=$(ELL), xplus=$(XPLUS_TAG)")

    save_plot_files(unstableplot, "qnm_plot_unstable-$(FILETAG)")
end

if !isempty(oscillatory_modes)
    xlo_o, xhi_o = recommended_xlims(oscillatory_modes)
    ylo_o, yhi_o = recommended_ylims(oscillatory_modes)

    oscplot = scatter(xo, yo;
        ms = 5,
        alpha = 1.0,
        label = "oscillatory stable"
    )

    hline!(oscplot, [0.0]; label = "Im Omega = 0", linestyle = :dash, alpha = 0.4)

    xlims!(oscplot, xlo_o, xhi_o)
    ylims!(oscplot, ylo_o, yhi_o)

    xlabel!(oscplot, "Re Omega")
    ylabel!(oscplot, "Im Omega")
    title!(oscplot, "Oscillatory SAdS QNMs: s=$(SPIN), ell=$(ELL), xplus=$(XPLUS_TAG)")

    save_plot_files(oscplot, "qnm_plot_oscillatory-$(FILETAG)")
end

if !isempty(pure_imag_modes)
    xlo_p, xhi_p = recommended_xlims(pure_imag_modes)
    ylo_p, yhi_p = recommended_ylims(pure_imag_modes)

    pureplot = scatter(xpi, ypi;
        ms = 5,
        alpha = 1.0,
        label = "pure imaginary stable"
    )

    hline!(pureplot, [0.0]; label = "Im Omega = 0", linestyle = :dash, alpha = 0.4)

    xlims!(pureplot, xlo_p, xhi_p)
    ylims!(pureplot, ylo_p, yhi_p)

    xlabel!(pureplot, "Re Omega")
    ylabel!(pureplot, "Im Omega")
    title!(pureplot, "Purely imaginary SAdS QNMs: s=$(SPIN), ell=$(ELL), xplus=$(XPLUS_TAG)")

